USB_FIND = '\nXG_USB_ROOT=\'\'\nXG_USB_COUNT=0\nwhile read XG_SRC XG_MNT XG_FS XG_OPTS XG_REST; do\n  case "$XG_SRC" in /dev/sd*|/dev/mmcblk*) ;; *) continue ;; esac\n  if [ -f "$XG_MNT/backup-stock-to-usb.sh" ] && [ -f "$XG_MNT/collect-device-info.sh" ]; then\n    XG_USB_ROOT="$XG_MNT"\n    XG_USB_COUNT=$((XG_USB_COUNT + 1))\n  fi\ndone < /proc/mounts\nif [ "$XG_USB_COUNT" = 1 ]; then\n  export XG_USB_ROOT\n  printf \'USB_READY: %s\\n\' "$XG_USB_ROOT"\nelse\n  XG_USB_ROOT=\'\'\n  printf \'STOP: matching USB mounts=%s\\n\' "$XG_USB_COUNT"\nfi\n'
USB_BACKUP = '\nif [ -z "$XG_USB_ROOT" ]; then\n  printf \'STOP: run USB detection first\\n\'\nelse\n  XG_INFO_LOG="$XG_USB_ROOT/device-info-$(date +%Y%m%d-%H%M%S).txt"\n  sh "$XG_USB_ROOT/collect-device-info.sh" > "$XG_INFO_LOG" 2>&1\n  sh "$XG_USB_ROOT/backup-stock-to-usb.sh" "$XG_USB_ROOT"\nfi\n'
